package com.codex.ledger;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CodexLedgerPluginRunner
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CodexLedgerPlugin.class);
		RuneLite.main(args);
	}
}

package com.codex.ledger;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(CodexLedgerConfig.GROUP)
public interface CodexLedgerConfig extends Config
{
	String GROUP = "codexledger";

	@ConfigItem(
		keyName = "loginSummary",
		name = "Summary at login",
		description = "When you log in, write your worth and what prices did while you were away in the chat box",
		position = 0
	)
	default boolean loginSummary()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPlaque",
		name = "Worth plaque",
		description = "Show a small plaque in the game view with your worth and today's change",
		position = 1
	)
	default boolean showPlaque()
	{
		return false;
	}
}

package com.codex.ledger;

import com.codex.ledger.core.Day;
import com.codex.ledger.core.Ledger;
import com.codex.ledger.core.Report;
import com.codex.ledger.core.Store;
import com.codex.ledger.overlay.WorthPlaque;
import com.codex.ledger.ui.Format;
import com.codex.ledger.ui.ItemIcons;
import com.codex.ledger.ui.LedgerPanel;
import com.codex.ledger.ui.Sigil;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.inject.Provides;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.AsyncBufferedImage;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Codex Ledger",
	description = "Your net worth over time: bank, inventory, gear, Grand Exchange and more, with a day book of where your gold came from and went",
	tags = {"wealth", "net worth", "bank", "value", "gp", "profit", "grand exchange", "ledger", "codex"}
)
public class CodexLedgerPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CodexLedgerPlugin.class);
	private static final String LEDGER_KEY = "ledger";
	/** Ticks between revaluing what is held, about a minute. */
	private static final int REVALUE_TICKS = 100;
	/** Ticks between saves while something has changed. */
	private static final int SAVE_TICKS = 50;
	/** Ticks after login before the summary, so the exchange offers have arrived. */
	private static final int SUMMARY_TICKS = 8;
	private static final int GE_SLOTS = 8;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private Gson gson;

	@Inject
	private CodexLedgerConfig config;

	private final WorthPlaque plaque = new WorthPlaque();
	private final Map<Integer, String> names = new HashMap<>();
	@SuppressWarnings("unchecked")
	private final Map<Integer, Long>[] exchange = new Map[GE_SLOTS];

	private LedgerPanel panel;
	private NavigationButton navButton;

	private String profile;
	private Ledger ledger;
	private boolean dirty;
	private boolean unsaved;
	private int ticks;
	private int loggedInTicks = -1;
	private long worthAtLogin = -1;

	@Provides
	CodexLedgerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexLedgerConfig.class);
	}

	@Override
	protected void startUp()
	{
		ItemIcons icons = (itemId, onLoaded) ->
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(onLoaded);
			return image;
		};
		panel = new LedgerPanel(icons);
		navButton = NavigationButton.builder()
			.tooltip("Codex Ledger")
			.icon(Sigil.icon(16))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		plaque.setEnabled(config.showPlaque());
		overlayManager.add(plaque);
		clientThread.invokeLater(() ->
		{
			loadProfile();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loggedInTicks = 0;
				observeAll();
			}
			publish();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(plaque);
		clientToolbar.removeNavigation(navButton);
		clientThread.invokeLater(() ->
		{
			save();
			ledger = null;
			profile = null;
			names.clear();
			clearExchange();
		});
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			if (loggedInTicks < 0)
			{
				loggedInTicks = 0;
				worthAtLogin = ledger != null && ledger.isReady() ? ledger.getTotal() : -1;
			}
		}
		else if (state == GameState.LOGIN_SCREEN)
		{
			loggedInTicks = -1;
			clearExchange();
			save();
			dirty = true;
			publish();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		save();
		loadProfile();
		clearExchange();
		worthAtLogin = ledger != null && ledger.isReady() ? ledger.getTotal() : -1;
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			observeAll();
		}
		publish();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CodexLedgerConfig.GROUP.equals(event.getGroup()))
		{
			plaque.setEnabled(config.showPlaque());
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (client.getGameState() != GameState.LOGGED_IN || ledger == null)
		{
			return;
		}
		Store store = store(event.getContainerId());
		if (store != null)
		{
			ledger.observe(store, contents(event.getItemContainer()));
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		GrandExchangeOffer offer = event.getOffer();
		int slot = event.getSlot();
		if (ledger == null || slot < 0 || slot >= GE_SLOTS
			|| (offer.getState() == GrandExchangeOfferState.EMPTY && client.getGameState() != GameState.LOGGED_IN))
		{
			// The client clears every offer while logging in and hopping; those are not real.
			return;
		}
		exchange[slot] = offerContents(offer);
		Map<Integer, Long> all = new HashMap<>();
		for (Map<Integer, Long> s : exchange)
		{
			if (s != null)
			{
				s.forEach((id, q) -> all.merge(id, q, Long::sum));
			}
		}
		ledger.observe(Store.GRAND_EXCHANGE, all);
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (ledger == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ticks++;
		if (loggedInTicks >= 0)
		{
			loggedInTicks++;
		}
		if (!pricesReady())
		{
			return;
		}
		if (ledger.hasPending() || ticks % REVALUE_TICKS == 0)
		{
			if (ledger.settle(System.currentTimeMillis(), itemManager::getItemPrice, ZoneId.systemDefault()))
			{
				dirty = true;
				unsaved = true;
			}
		}
		if (loggedInTicks == SUMMARY_TICKS)
		{
			summary();
		}
		if (unsaved && ticks % SAVE_TICKS == 0)
		{
			save();
		}
		if (dirty && ticks % 2 == 0 || ticks % REVALUE_TICKS == 1)
		{
			publish();
		}
	}

	/** Prices load in the background after the client starts; nothing is valued before they are in. */
	private boolean pricesReady()
	{
		return itemManager.getItemPrice(ItemID.ABYSSAL_WHIP) > 0;
	}

	private static Store store(int containerId)
	{
		switch (containerId)
		{
			case InventoryID.BANK:
				return Store.BANK;
			case InventoryID.INV:
				return Store.INVENTORY;
			case InventoryID.WORN:
				return Store.EQUIPMENT;
			case InventoryID.SEED_VAULT:
				return Store.SEED_VAULT;
			case InventoryID.LOOTING_BAG:
				return Store.LOOTING_BAG;
			default:
				return null;
		}
	}

	private Map<Integer, Long> contents(ItemContainer container)
	{
		Map<Integer, Long> items = new HashMap<>();
		if (container == null)
		{
			return items;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() < 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			items.merge(itemManager.canonicalize(item.getId()), (long) item.getQuantity(), Long::sum);
		}
		return items;
	}

	/** What an offer holds right now: the items it has bought or has left to sell, and the coins in it. */
	private static Map<Integer, Long> offerContents(GrandExchangeOffer offer)
	{
		Map<Integer, Long> items = new HashMap<>();
		long coins;
		long held;
		switch (offer.getState())
		{
			case BUYING:
			case BOUGHT:
			case CANCELLED_BUY:
				held = offer.getQuantitySold();
				coins = offer.getPrice() * offer.getTotalQuantity() - offer.getSpent();
				break;
			case SELLING:
			case SOLD:
			case CANCELLED_SELL:
				held = offer.getTotalQuantity() - offer.getQuantitySold();
				coins = offer.getSpent();
				break;
			default:
				return items;
		}
		if (held > 0)
		{
			items.put(offer.getItemId(), held);
		}
		if (coins > 0)
		{
			items.merge(ItemID.COINS, coins, Long::sum);
		}
		return items;
	}

	/** Reads every place the client already has, for when the plugin starts with the player logged in. */
	private void observeAll()
	{
		for (int id : new int[]{InventoryID.INV, InventoryID.WORN, InventoryID.BANK, InventoryID.SEED_VAULT, InventoryID.LOOTING_BAG})
		{
			ItemContainer container = client.getItemContainer(id);
			if (container != null)
			{
				ledger.observe(store(id), contents(container));
			}
		}
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers != null)
		{
			Map<Integer, Long> all = new HashMap<>();
			for (int i = 0; i < offers.length && i < GE_SLOTS; i++)
			{
				if (offers[i] != null)
				{
					exchange[i] = offerContents(offers[i]);
					exchange[i].forEach((id, q) -> all.merge(id, q, Long::sum));
				}
			}
			ledger.observe(Store.GRAND_EXCHANGE, all);
		}
	}

	private void clearExchange()
	{
		for (int i = 0; i < GE_SLOTS; i++)
		{
			exchange[i] = null;
		}
	}

	private void loadProfile()
	{
		profile = configManager.getRSProfileKey();
		ledger = null;
		if (profile == null)
		{
			return;
		}
		try
		{
			String saved = configManager.getRSProfileConfiguration(CodexLedgerConfig.GROUP, LEDGER_KEY);
			if (saved != null && !saved.isEmpty())
			{
				Ledger read = gson.fromJson(saved, Ledger.class);
				ledger = read == null ? null : read.repair();
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Could not read the saved ledger, starting it afresh", e);
		}
		if (ledger == null)
		{
			ledger = new Ledger();
		}
		unsaved = false;
		dirty = true;
	}

	private void save()
	{
		if (profile == null || ledger == null || !unsaved)
		{
			return;
		}
		unsaved = false;
		configManager.setConfiguration(CodexLedgerConfig.GROUP, profile, LEDGER_KEY, gson.toJson(ledger));
	}

	private void summary()
	{
		if (!config.loginSummary() || ledger == null || !ledger.isReady())
		{
			return;
		}
		long total = ledger.getTotal();
		ZoneId zone = ZoneId.systemDefault();
		LocalDate today = Instant.now().atZone(zone).toLocalDate();
		long change = Report.of(ledger, 1, today, 0).change();
		ChatMessageBuilder line = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("Codex Ledger: ")
			.append(ChatColorType.NORMAL).append("your worth is ")
			.append(ChatColorType.HIGHLIGHT).append(Format.coins(total))
			.append(ChatColorType.NORMAL).append(", " + Format.signed(change) + " today.");
		if (worthAtLogin >= 0 && worthAtLogin != total)
		{
			line.append(" While you were away it moved " + Format.signed(total - worthAtLogin) + ".");
		}
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(line.build())
			.build());
	}

	/** Sends the panel a copy of the ledger with every name it needs, so Swing never reads what the client thread writes. */
	private void publish()
	{
		dirty = false;
		LedgerPanel target = panel;
		long now = System.currentTimeMillis();
		if (ledger == null)
		{
			plaque.show(null, 0);
			if (target != null)
			{
				SwingUtilities.invokeLater(() -> target.update(null, Collections.emptyMap(), null, LedgerPanel.State.LOGGED_OUT, now));
			}
			return;
		}
		Ledger copy = gson.fromJson(gson.toJson(ledger), Ledger.class).repair();
		for (int id : copy.holdings().keySet())
		{
			name(id);
		}
		for (Day day : copy.getDays())
		{
			for (int id : day.getItems().keySet())
			{
				name(id);
			}
		}
		Map<Integer, String> shownNames = new HashMap<>(names);
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		Player player = client.getLocalPlayer();
		String name = loggedIn && player != null ? player.getName() : null;
		LedgerPanel.State state = !loggedIn ? LedgerPanel.State.LOGGED_OUT : copy.isReady() ? LedgerPanel.State.READY : LedgerPanel.State.WAITING_FOR_BANK;
		if (copy.isReady() && loggedIn)
		{
			plaque.show(copy.getTotal(), Report.of(copy, 1, Instant.ofEpochMilli(now).atZone(ZoneId.systemDefault()).toLocalDate(), 0).change());
		}
		else
		{
			plaque.show(null, 0);
		}
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(copy, shownNames, name, state, now));
		}
	}

	private void name(int itemId)
	{
		names.computeIfAbsent(itemId, id -> itemManager.getItemComposition(id).getName());
	}
}

package com.codex.ledger.core;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * One page of the day book: the worth the day opened and closed on, its high and low, and how
 * the change splits into what the player gained or spent (play) and what prices did (market).
 */
public final class Day
{
	/** Items kept on a page once its day is over. */
	static final int KEPT_ITEMS = 16;
	/** Items a page may hold while its day is still being written. */
	static final int OPEN_ITEMS = 600;

	private String date;
	private long open;
	private long close;
	private long high;
	private long low;
	private long play;
	private long market;
	private Map<Integer, Flow> items = new HashMap<>();

	public Day()
	{
	}

	Day(String date, long open)
	{
		this.date = date;
		this.open = open;
		this.close = open;
		this.high = open;
		this.low = open;
	}

	void flow(int itemId, long quantity, long value, long drift)
	{
		if (value == 0 && drift == 0)
		{
			return;
		}
		items.computeIfAbsent(itemId, k -> new Flow()).add(quantity, value, drift);
		if (items.size() > OPEN_ITEMS)
		{
			trim(OPEN_ITEMS / 2);
		}
	}

	void totals(long play, long market, long close)
	{
		this.play += play;
		this.market += market;
		this.close = close;
		high = Math.max(high, close);
		low = Math.min(low, close);
	}

	/** Worth found in a place seen for the first time is opening balance, not a gain. */
	void found(long value)
	{
		open += value;
		high = Math.max(high, open);
		low = Math.min(low, open);
	}

	/** Keeps only the items that mattered most. */
	void trim(int keep)
	{
		if (items.size() <= keep)
		{
			return;
		}
		List<Map.Entry<Integer, Flow>> list = new ArrayList<>(items.entrySet());
		list.sort(Comparator.comparingLong((Map.Entry<Integer, Flow> e) -> e.getValue().weight()).reversed());
		Map<Integer, Flow> kept = new HashMap<>();
		for (int i = 0; i < keep; i++)
		{
			kept.put(list.get(i).getKey(), list.get(i).getValue());
		}
		items = kept;
	}

	public String getDate()
	{
		return date;
	}

	public long getOpen()
	{
		return open;
	}

	public long getClose()
	{
		return close;
	}

	public long getHigh()
	{
		return high;
	}

	public long getLow()
	{
		return low;
	}

	public long getPlay()
	{
		return play;
	}

	public long getMarket()
	{
		return market;
	}

	public long change()
	{
		return close - open;
	}

	public Map<Integer, Flow> getItems()
	{
		return items == null ? new HashMap<>() : items;
	}
}

package com.codex.ledger.core;

/**
 * What one item did to the account's worth over a stretch of time: how many came or went,
 * what that came to at the day's prices, and how much the price moving changed what was held.
 */
public final class Flow
{
	/** Net quantity gained (or lost, when negative). */
	private long q;
	/** Value gained or lost by quantity changing, at the price of the moment. */
	private long v;
	/** Value gained or lost by the price moving on what was already held. */
	private long d;

	public Flow()
	{
	}

	public Flow(long quantity, long value, long drift)
	{
		this.q = quantity;
		this.v = value;
		this.d = drift;
	}

	void add(long quantity, long value, long drift)
	{
		q += quantity;
		v += value;
		d += drift;
	}

	void add(Flow other)
	{
		add(other.q, other.v, other.d);
	}

	public long getQuantity()
	{
		return q;
	}

	public long getValue()
	{
		return v;
	}

	public long getDrift()
	{
		return d;
	}

	/** How much this item mattered either way, for ranking and trimming. */
	long weight()
	{
		return Math.abs(v) + Math.abs(d);
	}
}

package com.codex.ledger.core;

import java.util.ArrayList;
import java.util.List;

/**
 * Keeps the worth history small without losing its shape: fine detail for the last two days,
 * a point every few hours for the last six weeks, and one a day beyond that.
 */
public final class History
{
	static final long MINUTE = 60_000L;
	static final long HOUR = 60 * MINUTE;
	static final long DAY = 24 * HOUR;
	/** Points kept at most, whatever their age. */
	static final int MAX_POINTS = 1_200;

	private History()
	{
	}

	/** The width of the time bucket a point of this age shares with its neighbours. */
	static long bucket(long age)
	{
		if (age < 2 * DAY)
		{
			return 15 * MINUTE;
		}
		if (age < 45 * DAY)
		{
			return 3 * HOUR;
		}
		return DAY;
	}

	/** Keeps the last point in every bucket, oldest first. The newest point is always kept. */
	public static List<Ledger.Point> compact(List<Ledger.Point> points, long now)
	{
		List<Ledger.Point> kept = new ArrayList<>();
		for (int i = 0; i < points.size(); i++)
		{
			Ledger.Point p = points.get(i);
			if (i == points.size() - 1)
			{
				kept.add(p);
				break;
			}
			Ledger.Point next = points.get(i + 1);
			long size = bucket(now - p.getTime());
			long nextSize = bucket(now - next.getTime());
			if (size != nextSize || p.getTime() / size != next.getTime() / size)
			{
				kept.add(p);
			}
		}
		while (kept.size() > MAX_POINTS)
		{
			kept.remove(0);
		}
		return kept;
	}
}

package com.codex.ledger.core;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * An account's ledger: what it holds in each place, what each item was last worth, the worth
 * over time and a day book of where it came from and went.
 *
 * <p>Places are seen one at a time (the bank only while it is open), so the ledger remembers each
 * as last seen. Changes are gathered and settled together once a tick, so an item moving from the
 * bank to the inventory is a move, not a loss and a gain. Every settle splits the change in worth
 * into play (items gained or spent, at today's price) and market (prices moving on what was held).
 *
 * <p>The ledger begins when the bank is first seen; until then the total is only part of the story.
 */
public final class Ledger
{
	/** Pages kept in the day book. */
	public static final int DAYS = 120;

	private Map<Store, Holding> stores = new LinkedHashMap<>();
	private Map<Integer, Long> prices = new HashMap<>();
	private List<Point> history = new ArrayList<>();
	private List<Day> days = new ArrayList<>();
	private long total;
	private long since;

	private transient Map<Store, Map<Integer, Long>> pending;

	/** One place as last seen. */
	public static final class Holding
	{
		private long seen;
		private Map<Integer, Long> items;

		public Holding()
		{
		}

		Holding(long seen, Map<Integer, Long> items)
		{
			this.seen = seen;
			this.items = items;
		}

		public long getSeen()
		{
			return seen;
		}

		public Map<Integer, Long> getItems()
		{
			return items == null ? Collections.emptyMap() : items;
		}
	}

	/** The worth at a moment. */
	public static final class Point
	{
		private long t;
		private long v;

		public Point()
		{
		}

		public Point(long time, long value)
		{
			this.t = time;
			this.v = value;
		}

		public long getTime()
		{
			return t;
		}

		public long getValue()
		{
			return v;
		}
	}

	/** Records what a place holds now; it counts at the next settle. Quantities of zero or less are dropped. */
	public void observe(Store store, Map<Integer, Long> items)
	{
		Map<Integer, Long> copy = new HashMap<>();
		for (Map.Entry<Integer, Long> e : items.entrySet())
		{
			if (e.getValue() != null && e.getValue() > 0)
			{
				copy.merge(e.getKey(), e.getValue(), Long::sum);
			}
		}
		if (pending == null)
		{
			pending = new EnumMap<>(Store.class);
		}
		pending.put(store, copy);
	}

	public boolean hasPending()
	{
		return pending != null && !pending.isEmpty();
	}

	/**
	 * Counts everything observed since the last settle and revalues what is held at today's prices.
	 *
	 * @return true when the worth or the day book changed
	 */
	public boolean settle(long now, Prices market, ZoneId zone)
	{
		Map<Integer, Long> before = aggregate();
		Map<Integer, Long> found = new HashMap<>();
		boolean wasReady = isReady();
		if (pending != null)
		{
			collectToBank();
			for (Map.Entry<Store, Map<Integer, Long>> e : pending.entrySet())
			{
				if (!stores.containsKey(e.getKey()))
				{
					for (Map.Entry<Integer, Long> item : e.getValue().entrySet())
					{
						found.merge(item.getKey(), item.getValue(), Long::sum);
					}
				}
				stores.put(e.getKey(), new Holding(now, e.getValue()));
			}
			pending.clear();
		}
		for (Map.Entry<Integer, Long> e : found.entrySet())
		{
			before.merge(e.getKey(), e.getValue(), Long::sum);
		}
		Map<Integer, Long> after = aggregate();

		Set<Integer> ids = new HashSet<>(before.keySet());
		ids.addAll(after.keySet());
		boolean ready = isReady();
		boolean opening = ready && !wasReady;
		Day day = ready && !opening ? today(now, zone) : null;
		long play = 0;
		long drift = 0;
		long foundValue = 0;
		long worth = 0;
		for (int id : ids)
		{
			long oldQ = before.getOrDefault(id, 0L);
			long newQ = after.getOrDefault(id, 0L);
			Long known = prices.get(id);
			long price = market.price(id);
			if (price <= 0)
			{
				price = known != null ? known : 0;
			}
			long oldPrice = known != null ? known : price;
			long value = (newQ - oldQ) * price;
			long moved = oldQ * (price - oldPrice);
			worth += newQ * price;
			foundValue += found.getOrDefault(id, 0L) * oldPrice;
			play += value;
			drift += moved;
			if (day != null && (newQ != oldQ || moved != 0))
			{
				day.flow(id, newQ - oldQ, value, moved);
			}
			if (newQ > 0)
			{
				prices.put(id, price);
			}
			else
			{
				prices.remove(id);
			}
		}

		if (opening)
		{
			since = now;
			history.clear();
			days.clear();
			total = worth;
			today(now, zone);
			history.add(new Point(now, worth));
			return true;
		}
		boolean changed = worth != total || play != 0 || drift != 0;
		total = worth;
		if (day != null)
		{
			if (foundValue != 0)
			{
				day.found(foundValue);
			}
			day.totals(play, drift, worth);
			if (changed || history.isEmpty())
			{
				record(now, worth);
			}
		}
		return changed;
	}

	/**
	 * Items that leave the Grand Exchange without reaching the inventory were collected to the
	 * bank, so they are put there now rather than counted lost until the bank is next opened.
	 * Opening the bank replaces this guess with what is really there.
	 */
	private void collectToBank()
	{
		Map<Integer, Long> exchange = pending.get(Store.GRAND_EXCHANGE);
		Holding bank = stores.get(Store.BANK);
		Holding oldExchange = stores.get(Store.GRAND_EXCHANGE);
		if (exchange == null || bank == null || oldExchange == null || pending.containsKey(Store.BANK))
		{
			return;
		}
		Map<Integer, Long> invNow = pending.get(Store.INVENTORY);
		Holding invThen = stores.get(Store.INVENTORY);
		Map<Integer, Long> banked = null;
		for (Map.Entry<Integer, Long> e : oldExchange.getItems().entrySet())
		{
			long left = e.getValue() - exchange.getOrDefault(e.getKey(), 0L);
			if (left <= 0)
			{
				continue;
			}
			if (invNow != null)
			{
				long before = invThen == null ? 0 : invThen.getItems().getOrDefault(e.getKey(), 0L);
				left -= Math.max(0, invNow.getOrDefault(e.getKey(), 0L) - before);
			}
			if (left > 0)
			{
				if (banked == null)
				{
					banked = new HashMap<>(bank.getItems());
				}
				banked.merge(e.getKey(), left, Long::sum);
			}
		}
		if (banked != null)
		{
			stores.put(Store.BANK, new Holding(bank.getSeen(), banked));
		}
	}

	/** Today's page, opening a new one on the worth carried over when the date has turned. */
	private Day today(long now, ZoneId zone)
	{
		String date = Instant.ofEpochMilli(now).atZone(zone).toLocalDate().toString();
		Day last = days.isEmpty() ? null : days.get(days.size() - 1);
		if (last != null && date.equals(last.getDate()))
		{
			return last;
		}
		if (last != null)
		{
			last.trim(Day.KEPT_ITEMS);
		}
		Day day = new Day(date, total);
		days.add(day);
		while (days.size() > DAYS)
		{
			days.remove(0);
		}
		return day;
	}

	private void record(long now, long worth)
	{
		history.add(new Point(now, worth));
		history = History.compact(history, now);
	}

	private Map<Integer, Long> aggregate()
	{
		Map<Integer, Long> all = new HashMap<>();
		for (Holding h : stores.values())
		{
			for (Map.Entry<Integer, Long> e : h.getItems().entrySet())
			{
				all.merge(e.getKey(), e.getValue(), Long::sum);
			}
		}
		return all;
	}

	/** True once the bank has been seen, which is when the ledger begins. */
	public boolean isReady()
	{
		return stores.containsKey(Store.BANK);
	}

	public long getTotal()
	{
		return total;
	}

	public long getSince()
	{
		return since;
	}

	public Map<Store, Holding> getStores()
	{
		return Collections.unmodifiableMap(stores);
	}

	/** What a place is worth at the last settle's prices. */
	public long value(Store store)
	{
		Holding h = stores.get(store);
		if (h == null)
		{
			return 0;
		}
		long sum = 0;
		for (Map.Entry<Integer, Long> e : h.getItems().entrySet())
		{
			sum += e.getValue() * prices.getOrDefault(e.getKey(), 0L);
		}
		return sum;
	}

	public long price(int itemId)
	{
		return prices.getOrDefault(itemId, 0L);
	}

	/** Every item held, across every place, with its quantity. */
	public Map<Integer, Long> holdings()
	{
		return aggregate();
	}

	public List<Point> getHistory()
	{
		return Collections.unmodifiableList(history);
	}

	/** Pages of the day book, oldest first. */
	public List<Day> getDays()
	{
		return Collections.unmodifiableList(days);
	}

	/** The day book's page for a date, or null. */
	public Day day(LocalDate date)
	{
		String key = date.toString();
		for (int i = days.size() - 1; i >= 0; i--)
		{
			if (key.equals(days.get(i).getDate()))
			{
				return days.get(i);
			}
		}
		return null;
	}

	/** Mends a ledger read back from storage, where any part may be missing. */
	public Ledger repair()
	{
		if (stores == null)
		{
			stores = new LinkedHashMap<>();
		}
		stores.values().removeIf(h -> h == null);
		stores.keySet().removeIf(s -> s == null);
		if (prices == null)
		{
			prices = new HashMap<>();
		}
		if (history == null)
		{
			history = new ArrayList<>();
		}
		history.removeIf(p -> p == null);
		if (days == null)
		{
			days = new ArrayList<>();
		}
		days.removeIf(d -> d == null || d.getDate() == null);
		return this;
	}
}

package com.codex.ledger.core;

/** Where the Ledger learns what an item is worth today. */
public interface Prices
{
	/** @return the item's price in coins, or 0 or less when it is not known */
	long price(int itemId);
}

package com.codex.ledger.core;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Where the gold went over a stretch of days: the change in worth split into play and market,
 * the items that brought the most in, the ones that took the most out, and the prices that moved.
 */
public final class Report
{
	/** One item's part in a report, or in the holdings. */
	public static final class Line
	{
		private final int itemId;
		private final long quantity;
		private final long value;
		private final long drift;

		public Line(int itemId, long quantity, long value, long drift)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.value = value;
			this.drift = drift;
		}

		public int getItemId()
		{
			return itemId;
		}

		public long getQuantity()
		{
			return quantity;
		}

		public long getValue()
		{
			return value;
		}

		public long getDrift()
		{
			return drift;
		}
	}

	private final LocalDate from;
	private final int days;
	private final long start;
	private final long end;
	private final long play;
	private final long market;
	private final List<Line> gains;
	private final List<Line> losses;
	private final List<Line> movers;

	private Report(LocalDate from, int days, long start, long end, long play, long market, List<Line> gains, List<Line> losses, List<Line> movers)
	{
		this.from = from;
		this.days = days;
		this.start = start;
		this.end = end;
		this.play = play;
		this.market = market;
		this.gains = gains;
		this.losses = losses;
		this.movers = movers;
	}

	/**
	 * @param span days to cover, today included; 0 or less covers the whole day book
	 * @param limit lines kept in each list
	 */
	public static Report of(Ledger ledger, int span, LocalDate today, int limit)
	{
		LocalDate from = span <= 0 ? null : today.minusDays(span - 1);
		long play = 0;
		long market = 0;
		int covered = 0;
		LocalDate first = null;
		Map<Integer, Flow> merged = new HashMap<>();
		for (Day day : ledger.getDays())
		{
			LocalDate date = LocalDate.parse(day.getDate());
			if (from != null && date.isBefore(from))
			{
				continue;
			}
			if (first == null)
			{
				first = date;
			}
			covered++;
			play += day.getPlay();
			market += day.getMarket();
			for (Map.Entry<Integer, Flow> e : day.getItems().entrySet())
			{
				merged.computeIfAbsent(e.getKey(), k -> new Flow()).add(e.getValue());
			}
		}
		return build(first != null ? first : today, covered, ledger.getTotal(), play, market, merged, limit);
	}

	/** One page of the day book on its own, from the worth it opened on to the worth it closed on. */
	public static Report page(Day day, int limit)
	{
		return build(LocalDate.parse(day.getDate()), 1, day.getClose(), day.getPlay(), day.getMarket(), day.getItems(), limit);
	}

	private static Report build(LocalDate from, int covered, long end, long play, long market, Map<Integer, Flow> merged, int limit)
	{
		List<Line> gains = new ArrayList<>();
		List<Line> losses = new ArrayList<>();
		List<Line> movers = new ArrayList<>();
		for (Map.Entry<Integer, Flow> e : merged.entrySet())
		{
			Flow f = e.getValue();
			Line line = new Line(e.getKey(), f.getQuantity(), f.getValue(), f.getDrift());
			if (f.getValue() > 0)
			{
				gains.add(line);
			}
			else if (f.getValue() < 0)
			{
				losses.add(line);
			}
			if (f.getDrift() != 0)
			{
				movers.add(line);
			}
		}
		gains.sort(Comparator.comparingLong(Line::getValue).reversed());
		losses.sort(Comparator.comparingLong(Line::getValue));
		movers.sort(Comparator.comparingLong((Line l) -> Math.abs(l.getDrift())).reversed());
		return new Report(from, covered, end - play - market, end, play, market,
			head(gains, limit), head(losses, limit), head(movers, limit));
	}

	/** Every item held, most valuable first. */
	public static List<Line> holdings(Ledger ledger, int limit)
	{
		List<Line> lines = new ArrayList<>();
		for (Map.Entry<Integer, Long> e : ledger.holdings().entrySet())
		{
			long value = e.getValue() * ledger.price(e.getKey());
			if (value > 0)
			{
				lines.add(new Line(e.getKey(), e.getValue(), value, 0));
			}
		}
		lines.sort(Comparator.comparingLong(Line::getValue).reversed());
		return head(lines, limit);
	}

	private static List<Line> head(List<Line> list, int limit)
	{
		return Collections.unmodifiableList(new ArrayList<>(list.subList(0, Math.min(limit, list.size()))));
	}

	public LocalDate getFrom()
	{
		return from;
	}

	/** Pages of the day book the report covers. */
	public int getDays()
	{
		return days;
	}

	public long getStart()
	{
		return start;
	}

	public long getEnd()
	{
		return end;
	}

	public long change()
	{
		return end - start;
	}

	public long getPlay()
	{
		return play;
	}

	public long getMarket()
	{
		return market;
	}

	public List<Line> getGains()
	{
		return gains;
	}

	public List<Line> getLosses()
	{
		return losses;
	}

	public List<Line> getMovers()
	{
		return movers;
	}
}

package com.codex.ledger.core;

/** The places the Ledger counts wealth in. Each is seen on its own and remembered until seen again. */
public enum Store
{
	BANK("Bank"),
	INVENTORY("Inventory"),
	EQUIPMENT("Worn"),
	GRAND_EXCHANGE("Grand Exchange"),
	SEED_VAULT("Seed vault"),
	LOOTING_BAG("Looting bag");

	private final String label;

	Store(String label)
	{
		this.label = label;
	}

	public String getLabel()
	{
		return label;
	}
}

package com.codex.ledger.overlay;

import com.codex.ledger.ui.Format;
import com.codex.ledger.ui.Sigil;
import com.codex.ledger.ui.Theme;
import com.codex.ledger.ui.Ui;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/** A slim gilt plaque in the game view with the account's worth and today's change. It draws what the plugin hands it. */
public class WorthPlaque extends Overlay
{
	private static final int PAD = 7;

	private volatile long[] view;
	private volatile boolean enabled;

	public WorthPlaque()
	{
		setPosition(OverlayPosition.TOP_LEFT);
	}

	/** @param worth the worth, or null to hide the plaque */
	public void show(Long worth, long today)
	{
		view = worth == null ? null : new long[]{worth, today};
	}

	public void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		long[] v = view;
		if (!enabled || v == null)
		{
			return null;
		}
		Theme.smooth(g);
		String worth = Format.coins(v[0]);
		String today = Format.signed(v[1]) + " today";

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int icon = 14;
		int width = PAD + icon + 6 + bold.stringWidth(worth) + 10 + small.stringWidth(today) + PAD;
		int height = Math.max(icon, bold.getHeight()) + PAD;

		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, width - 1, height - 1, 10, 10);
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 230), 0, height, Theme.alpha(Theme.INK_DEEP, 230)));
		g.fill(shape);
		g.setColor(Theme.alpha(Theme.GOLD, 170));
		g.draw(shape);

		int x = PAD;
		Sigil.paint(g, x, (height - icon) / 2f, icon);
		x += icon + 6;
		int base = (height + bold.getAscent()) / 2 - 2;
		g.setFont(Theme.title());
		Ui.shadowed(g, worth, x, base, Theme.GOLD_BRIGHT);
		x += bold.stringWidth(worth) + 10;
		g.setFont(Theme.small());
		Ui.shadowed(g, today, x, base, Theme.signed(v[1]));
		return new Dimension(width, height);
	}
}

package com.codex.ledger.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.ledger.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.ledger.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.ledger.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * The crest at the top of the panel: the Ledger's medallion, the account's worth in large gilt
 * figures, and what it did today, this week and this month.
 */
public class Crest extends JComponent
{
	private static final int HEIGHT = 104;

	private final Animator count = new Animator(this);
	private String player;
	private String status = "Log in to open the ledger";
	private long total;
	private boolean known;
	private final long[] changes = new long[3];
	private final boolean[] hasChange = new boolean[3];
	private static final String[] PERIODS = {"Today", "Week", "Month"};

	public Crest()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
	}

	/**
	 * @param status a line in place of the changes, or null to show them
	 * @param changes today, the week and the month; null for any not yet known
	 */
	public void update(String player, Long total, String status, Long[] changes)
	{
		this.player = player;
		this.status = status;
		this.known = total != null;
		if (total != null)
		{
			boolean animate = this.total != 0 && Math.abs(total - this.total) < Math.max(1, this.total);
			this.total = total;
			count.set(total, animate);
		}
		for (int i = 0; i < 3; i++)
		{
			hasChange[i] = changes != null && changes[i] != null;
			this.changes[i] = hasChange[i] ? changes[i] : 0;
		}
		repaint();
	}

	/**
	 * Draws text at twice the size of the game's bold font by doubling every pixel, the way the
	 * game itself draws large numbers, so the figures stay crisp instead of being re-rasterised.
	 *
	 * @return the width drawn
	 */
	private static int paintLarge(Graphics2D g, String text, int x, int y)
	{
		Font font = Theme.title();
		FontMetrics fm = g.getFontMetrics(font);
		int w = Math.max(1, fm.stringWidth(text) + 1);
		int h = fm.getHeight() + 1;
		BufferedImage small = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = small.createGraphics();
		sg.setFont(font);
		sg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int base = fm.getAscent();
		sg.setColor(Color.BLACK);
		sg.drawString(text, 1, base + 1);
		sg.setPaint(new GradientPaint(0, base - fm.getAscent() + 3, Theme.GOLD_BRIGHT, 0, base, Theme.GOLD));
		sg.drawString(text, 0, base);
		sg.dispose();
		Graphics2D lg = (Graphics2D) g.create();
		lg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		lg.drawImage(small, x, y - 2 * fm.getAscent() + 22, w * 2, h * 2, null);
		lg.dispose();
		return w * 2;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.22), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// The medallion: a gilt ring with the mark inside, lit from above.
		int mx = 10;
		int my = 14;
		int md = 54;
		g.setPaint(new RadialGradientPaint(mx + md / 2f, my + md / 3f, md * 0.7f, new float[]{0, 1},
			new Color[]{Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35), Theme.INK_DEEP}));
		g.fill(new Ellipse2D.Float(mx, my, md, md));
		g.setStroke(new BasicStroke(2f));
		g.setPaint(new GradientPaint(mx, my, Theme.GOLD_BRIGHT, mx, my + md, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(mx + 1, my + 1, md - 2, md - 2));
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 70));
		g.draw(new Ellipse2D.Float(mx + 5, my + 5, md - 10, md - 10));
		Sigil.paint(g, mx + 11, my + 11, md - 22);

		int tx = mx + md + 12;
		int room = w - tx - 8;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String heading = (player != null ? player + "  -  " : "") + "NET WORTH";
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(heading, small, room), tx, 22);

		String figure = known ? Format.coins(Math.round(count.get())) : "-";
		int top = 27;
		int figureW = paintLarge(g, figure, tx, top);
		if (known)
		{
			g.setFont(Theme.small());
			g.setColor(Theme.GOLD_DIM);
			g.drawString("gp", tx + figureW + 3, top + 18);
		}
		int fy = top + 26;
		int cy = fy + 24;
		g.setFont(Theme.small());
		if (status != null)
		{
			g.setColor(Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.3));
			g.drawString(Ui.clip(status, small, room), tx, cy);
		}
		else
		{
			int cw = room / 3;
			for (int i = 0; i < 3; i++)
			{
				int x = tx + i * cw;
				g.setColor(Theme.TEXT_FAINT);
				g.drawString(PERIODS[i], x, cy - 11);
				String value = hasChange[i] ? Format.signed(changes[i]) : "-";
				Ui.shadowed(g, Ui.clip(value, small, cw - 4), x, cy + 1, hasChange[i] ? Theme.signed(changes[i]) : Theme.TEXT_FAINT);
			}
		}

		// The gilt rule under the crest, with a diamond at its middle.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
	}
}

package com.codex.ledger.ui;

import com.codex.ledger.core.Day;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.time.LocalDate;
import javax.swing.JComponent;

/**
 * One page of the day book in the list: the date and the worth it closed on, the change, and a
 * slim two-part bar for how much of it was play and how much was market.
 */
class DayRow extends JComponent
{
	private final Day day;
	private final long scale;
	private final boolean selected;
	private boolean hover;

	DayRow(Day day, long scale, boolean selected, Runnable onClick)
	{
		this.day = day;
		this.scale = Math.max(1, scale);
		this.selected = selected;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 40));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setToolTipText("Play " + Format.signed(day.getPlay()) + ", market " + Format.signed(day.getMarket())
			+ ". High " + Format.coins(day.getHigh()) + ", low " + Format.coins(day.getLow()) + ".");
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (contains(e.getPoint()))
				{
					onClick.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, hover ? Theme.CARD_HOVER : Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(shape);
		long change = day.change();
		g.setClip(shape);
		g.setColor(Theme.signed(change));
		g.fillRect(0, 0, 3, h);
		g.setClip(null);
		g.setColor(selected ? Theme.alpha(Theme.GOLD, 160) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT);
		g.draw(shape);

		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		String date = Format.day(LocalDate.parse(day.getDate()));
		Ui.shadowed(g, date, 10, 4 + fm.getAscent(), selected ? Theme.GOLD_BRIGHT : Theme.TEXT);
		String text = Format.signed(change);
		Ui.shadowed(g, text, w - 9 - fm.stringWidth(text), 4 + fm.getAscent(), Theme.signed(change));

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_FAINT);
		g.drawString("closed " + Format.coins(day.getClose()), 10, h - 13);

		// Play and market side by side, scaled against the busiest day in the list.
		int bx = w - 9 - 70;
		int by = h - 17;
		int bw = 70;
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(bx, by, bw, 4, 4, 4));
		g.fill(new RoundRectangle2D.Float(bx, by + 6, bw, 4, 4, 4));
		bar(g, bx, by, bw, day.getPlay(), day.getPlay() >= 0 ? Theme.GAIN : Theme.LOSS);
		bar(g, bx, by + 6, bw, day.getMarket(), day.getMarket() >= 0 ? Theme.MARKET : Theme.EMBER);
		g.dispose();
	}

	private void bar(Graphics2D g, int x, int y, int w, long value, java.awt.Color color)
	{
		if (value == 0)
		{
			return;
		}
		float len = Math.max(2, w * (float) Math.min(1, Math.abs(value) / (double) scale));
		g.setColor(color);
		g.fill(new RoundRectangle2D.Float(x, y, len, 4, 4, 4));
	}
}

package com.codex.ledger.ui;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/** Coins, changes, durations and dates in the short forms the panel uses. */
public final class Format
{
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("EEEE d MMMM yyyy", Locale.ENGLISH);
	private static final DateTimeFormatter SHORT = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter MONTH = DateTimeFormatter.ofPattern("MMM yy", Locale.ENGLISH);

	private Format()
	{
	}

	/** "8,240", "41.2k", "412k", "1.24M". */
	public static String amount(long n)
	{
		if (n < 10_000)
		{
			return String.format(Locale.ENGLISH, "%,d", n);
		}
		if (n < 100_000)
		{
			return trim(n / 1_000.0, 1) + "k";
		}
		if (n < 1_000_000)
		{
			return Math.round(n / 1_000.0) + "k";
		}
		if (n < 10_000_000)
		{
			return trim(n / 1_000_000.0, 2) + "M";
		}
		if (n < 1_000_000_000)
		{
			return trim(n / 1_000_000.0, 1) + "M";
		}
		return trim(n / 1_000_000_000.0, 2) + "B";
	}

	/** Coins in the short form, negative amounts with a minus: "812.4M", "-45.2k". */
	public static String coins(long gp)
	{
		return gp < 0 ? "-" + amount(-gp) : amount(gp);
	}

	/** A change with its sign: "+3.2M", "-412k", "0". */
	public static String signed(long gp)
	{
		return gp > 0 ? "+" + amount(gp) : gp < 0 ? "-" + amount(-gp) : "0";
	}

	/** A quantity change with its sign, written in full: "+1,240", "-6". */
	public static String count(long n)
	{
		return (n > 0 ? "+" : n < 0 ? "-" : "") + String.format(Locale.ENGLISH, "%,d", Math.abs(n));
	}

	/** A share as a whole percent, or "<1%". */
	public static String percent(double share)
	{
		if (share > 0 && share < 0.01)
		{
			return "<1%";
		}
		return Math.round(share * 100) + "%";
	}

	/** "just now", "12m ago", "3h ago", "2d ago". */
	public static String ago(long ms)
	{
		long minutes = Math.max(0, ms) / 60_000;
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + "m ago";
		}
		if (minutes < 48 * 60)
		{
			return minutes / 60 + "h ago";
		}
		return minutes / (24 * 60) + "d ago";
	}

	private static String trim(double value, int places)
	{
		String text = String.format(Locale.ENGLISH, "%." + places + "f", value);
		while (text.contains(".") && (text.endsWith("0") || text.endsWith(".")))
		{
			text = text.substring(0, text.length() - 1);
		}
		return text;
	}

	/** "2h 14m", "38m", "under a minute". */
	public static String duration(long ms)
	{
		long minutes = ms / 60_000;
		if (minutes < 1)
		{
			return "under a minute";
		}
		if (minutes < 60)
		{
			return minutes + "m";
		}
		return minutes / 60 + "h " + minutes % 60 + "m";
	}

	/** "14:02" in the player's own time. */
	public static String time(long epochMs)
	{
		return CLOCK.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Thu 16 Oct". */
	public static String day(long epochMs)
	{
		return DAY.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "16 Oct". */
	public static String shortDay(long epochMs)
	{
		return SHORT.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Oct 26". */
	public static String month(long epochMs)
	{
		return MONTH.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Thu 16 Oct" for a day book date. */
	public static String day(java.time.LocalDate date)
	{
		return DAY.format(date);
	}

	/** "Thursday 16 October 2026". */
	public static String date(long epochMs)
	{
		return DATE.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** An item stack the way the game writes it: "950", "45K", "12M". */
	public static String stack(long n)
	{
		if (n < 100_000)
		{
			return String.valueOf(n);
		}
		if (n < 10_000_000)
		{
			return n / 1_000 + "K";
		}
		return n / 1_000_000 + "M";
	}

	/** The colour the game writes a stack of that size in. */
	public static java.awt.Color stackColor(long n)
	{
		return n < 100_000 ? Theme.QTY_YELLOW : n < 10_000_000 ? Theme.QTY_WHITE : Theme.QTY_GREEN;
	}
}

package com.codex.ledger.ui;

import java.awt.image.BufferedImage;

/** Where the panel gets item pictures; the plugin answers from RuneLite's item manager. */
public interface ItemIcons
{
	/**
	 * @param onLoaded run once if the picture arrives later than this call
	 * @return the picture, possibly still blank, or null
	 */
	BufferedImage icon(int itemId, Runnable onLoaded);
}

package com.codex.ledger.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * One item's line: the item in a dark well like a bank slot, its name and a quiet note under it,
 * the amount on the right in its colour, and optionally a bar for its share of the whole.
 */
class ItemRow extends JComponent
{
	private static final int WELL = 32;

	private final int itemId;
	private final String name;
	private final String note;
	private final String amount;
	private final Color color;
	private final double share;
	private final ItemIcons icons;

	/** @param share 0 to 1 for a share bar, or below 0 for none */
	ItemRow(int itemId, String name, String note, String amount, Color color, double share, ItemIcons icons, String tip)
	{
		this.itemId = itemId;
		this.name = name;
		this.note = note;
		this.amount = amount;
		this.color = color;
		this.share = share;
		this.icons = icons;
		setOpaque(false);
		setPreferredSize(new Dimension(10, share >= 0 ? WELL + 10 : WELL + 4));
		setToolTipText(tip);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int y = share >= 0 ? 5 : 2;
		RoundRectangle2D well = new RoundRectangle2D.Float(0.5f, y + 0.5f, WELL + 4, WELL - 1, 7, 7);
		g.setPaint(new GradientPaint(0, y, Theme.INK_DEEP, 0, y + WELL, Theme.mix(Theme.INK_DEEP, Theme.CARD, 0.6)));
		g.fill(well);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(well);
		BufferedImage icon = icons == null ? null : icons.icon(itemId, this::repaint);
		if (icon != null)
		{
			g.drawImage(icon, 2 + (WELL - icon.getWidth()) / 2, y + (WELL - icon.getHeight()) / 2 + 1, null);
		}

		int tx = WELL + 12;
		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		int aw = fm.stringWidth(amount);
		int base = (share >= 0 ? 0 : y) + fm.getAscent() + 1;
		Ui.shadowed(g, amount, w - aw, base, color);
		Ui.shadowed(g, Ui.clip(name, fm, w - tx - aw - 8), tx, base, Theme.TEXT);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		if (share >= 0)
		{
			int by = getHeight() - 6;
			int bw = w - tx;
			String pct = Format.percent(share);
			int pw = small.stringWidth(pct);
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, bw - pw - 8), tx, by - 3);
			g.drawString(pct, w - pw, by - 3);
			RoundRectangle2D track = new RoundRectangle2D.Float(tx, by, bw, 4, 4, 4);
			g.setColor(Theme.INK_DEEP);
			g.fill(track);
			float fill = (float) Math.max(3, bw * Math.max(0, Math.min(1, share)));
			g.setPaint(new GradientPaint(tx, 0, Theme.mix(color, Theme.INK, 0.4), tx + bw, 0, color));
			g.fill(new RoundRectangle2D.Float(tx, by, fill, 4, 4, 4));
		}
		else if (note != null)
		{
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - tx), tx, y + WELL - 6);
		}
		g.dispose();
	}
}

package com.codex.ledger.ui;

import com.codex.ledger.core.Day;
import com.codex.ledger.core.Ledger;
import com.codex.ledger.core.Report;
import com.codex.ledger.core.Store;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.GridLayout;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The Ledger side panel: the crest, then three pages. Worth is the line of the account's worth
 * over time and where it is kept, Day book is where the gold came from and went, and Hoard is
 * everything held, most valuable first.
 */
public class LedgerPanel extends PluginPanel
{
	static final int WIDTH = 200;
	private static final String[] TABS = {"worth", "daybook", "hoard"};
	private static final String[] RANGES = {"Day", "Week", "Month", "Year", "All"};
	private static final long[] RANGE_MS = {86_400_000L, 7 * 86_400_000L, 30 * 86_400_000L, 365 * 86_400_000L, 0};
	private static final int[] RANGE_DAYS = {1, 7, 30, 365, 0};
	private static final String[] SPANS = {"Today", "7 days", "30 days", "All"};
	private static final int[] SPAN_DAYS = {1, 7, 30, 0};
	private static final int LINES = 6;
	private static final int PAGES = 14;
	private static final int HOARD = 40;

	/** What the panel has to show. */
	public enum State
	{
		LOGGED_OUT,
		WAITING_FOR_BANK,
		READY
	}

	private final ItemIcons icons;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Worth", "Day book", "Hoard");
	private final Segmented range = new Segmented(false, RANGES);
	private final Segmented span = new Segmented(false, SPANS);
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane worth = scroller();
	private final JScrollPane daybook = scroller();
	private final JScrollPane hoard = scroller();

	private Ledger ledger;
	private Map<Integer, String> names = Collections.emptyMap();
	private State state = State.LOGGED_OUT;
	private long now;
	private ZoneId zone = ZoneId.systemDefault();
	private String openDay;

	public LedgerPanel(ItemIcons icons)
	{
		super(false);
		this.icons = icons;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		content.add(worth, TABS[0]);
		content.add(daybook, TABS[1]);
		content.add(hoard, TABS[2]);
		add(content, BorderLayout.CENTER);

		tabs.onChange(this::showTab);
		range.setSelected(1, false);
		range.onChange(i -> rebuildWorth());
		span.onChange(i ->
		{
			openDay = null;
			rebuildDaybook();
		});
		rebuild();
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/**
	 * Called on the Swing thread whenever the ledger changes.
	 *
	 * @param ledger a copy the panel may keep, or null when no account is open
	 * @param names item names for every item the ledger mentions
	 */
	public void update(Ledger ledger, Map<Integer, String> names, String player, State state, long now)
	{
		this.ledger = ledger;
		this.names = names;
		this.state = state;
		this.now = now;
		updateCrest(player);
		rebuild();
	}

	/** Opens one tab, for previews and tests. */
	public void showTab(int index)
	{
		tabs.setSelected(index, false);
		cards.show(content, TABS[index]);
	}

	/** Picks the worth chart's range, for previews and tests. */
	public void showRange(int index)
	{
		range.setSelected(index, false);
		rebuildWorth();
	}

	/** Opens one day book page by date, or the chosen span when null. */
	public void openDay(String date)
	{
		openDay = date;
		rebuildDaybook();
		SwingUtilities.invokeLater(() -> daybook.getVerticalScrollBar().setValue(0));
	}

	private LocalDate today()
	{
		return Instant.ofEpochMilli(now).atZone(zone).toLocalDate();
	}

	private void updateCrest(String player)
	{
		if (ledger == null)
		{
			crest.update(player, null, "Log in to open the ledger", null);
			return;
		}
		if (state != State.READY)
		{
			crest.update(player, ledger.getTotal(), state == State.LOGGED_OUT ? "Logged out, as last seen" : "Open your bank to begin", null);
			return;
		}
		Long[] changes = new Long[3];
		int[] spans = {1, 7, 30};
		for (int i = 0; i < 3; i++)
		{
			changes[i] = Report.of(ledger, spans[i], today(), 0).change();
		}
		crest.update(player, ledger.getTotal(), null, changes);
	}

	private void rebuild()
	{
		rebuildWorth();
		rebuildDaybook();
		rebuildHoard();
	}

	private boolean waiting(StackPanel stack)
	{
		if (ledger == null)
		{
			stack.add(note("The ledger is closed", "Log in and Codex Ledger counts what your account is worth: your bank, inventory, worn gear, Grand Exchange offers, seed vault and looting bag."));
			return true;
		}
		if (!ledger.isReady())
		{
			stack.add(note("Open your bank once", "The ledger begins the first time it sees your bank. After that it keeps count on its own, and the bank is remembered as last seen whenever it is closed."));
			return true;
		}
		return false;
	}

	// The Worth tab.

	private void rebuildWorth()
	{
		StackPanel stack = new StackPanel(8, 8);
		stack.add(range);
		if (waiting(stack))
		{
			if (ledger != null)
			{
				stack.add(new SectionHeader("Counted so far", Format.coins(ledger.getTotal())));
				stack.add(new StoreBreakdown(parts()));
			}
			replace(worth, stack);
			return;
		}
		int r = range.getSelected();
		long to = now;
		long from = RANGE_MS[r] > 0 ? now - RANGE_MS[r] : Math.min(ledger.getSince(), firstPoint());
		List<Ledger.Point> points = slice(ledger.getHistory(), from, to, ledger.getTotal());
		Card chart = new Card(new BorderLayout());
		chart.setBorder(new EmptyBorder(8, 8, 6, 8));
		chart.add(new WorthChart(points, from, to, r == 0), BorderLayout.CENTER);
		stack.add(chart);

		Report report = Report.of(ledger, RANGE_DAYS[r], today(), 1);
		Day best = null;
		Day worst = null;
		LocalDate start = RANGE_DAYS[r] > 0 ? today().minusDays(RANGE_DAYS[r] - 1) : null;
		for (Day d : ledger.getDays())
		{
			if (start != null && LocalDate.parse(d.getDate()).isBefore(start))
			{
				continue;
			}
			if (best == null || d.change() > best.change())
			{
				best = d;
			}
			if (worst == null || d.change() < worst.change())
			{
				worst = d;
			}
		}
		JPanel tiles = new JPanel(new GridLayout(2, 2, 6, 6));
		tiles.setOpaque(false);
		tiles.add(new StatTile(Format.signed(report.getPlay()), "Play", "gained and spent", Theme.signed(report.getPlay())));
		tiles.add(new StatTile(Format.signed(report.getMarket()), "Market", "prices moving", report.getMarket() >= 0 ? Theme.MARKET : Theme.EMBER));
		tiles.add(new StatTile(best == null ? "-" : Format.signed(best.change()), "Best day",
			best == null ? "" : Format.day(LocalDate.parse(best.getDate())), best == null ? Theme.TEXT_MUTED : Theme.signed(best.change())));
		tiles.add(new StatTile(worst == null ? "-" : Format.signed(worst.change()), "Worst day",
			worst == null ? "" : Format.day(LocalDate.parse(worst.getDate())), worst == null ? Theme.TEXT_MUTED : Theme.signed(worst.change())));
		stack.add(tiles);

		stack.add(new SectionHeader("Where it is kept", Format.coins(ledger.getTotal())));
		stack.add(new StoreBreakdown(parts()));
		stack.add(Ui.wrapped("Kept since " + Format.date(ledger.getSince()) + ". Places are counted as last seen, so the bank updates each time you open it.",
			Theme.small(), Theme.TEXT_FAINT, WIDTH - 10));
		replace(worth, stack);
	}

	private long firstPoint()
	{
		List<Ledger.Point> history = ledger.getHistory();
		return history.isEmpty() ? now : history.get(0).getTime();
	}

	/** The points in a range, starting at its left edge and running on to now. */
	static List<Ledger.Point> slice(List<Ledger.Point> history, long from, long to, long current)
	{
		List<Ledger.Point> out = new ArrayList<>();
		Ledger.Point before = null;
		for (Ledger.Point p : history)
		{
			if (p.getTime() < from)
			{
				before = p;
			}
			else if (p.getTime() <= to)
			{
				out.add(p);
			}
		}
		if (before != null)
		{
			out.add(0, new Ledger.Point(from, before.getValue()));
		}
		if (out.isEmpty() || out.get(out.size() - 1).getTime() < to)
		{
			out.add(new Ledger.Point(to, current));
		}
		return out;
	}

	private List<StoreBreakdown.Part> parts()
	{
		List<StoreBreakdown.Part> parts = new ArrayList<>();
		Map<Store, Ledger.Holding> stores = ledger.getStores();
		for (Store s : Store.values())
		{
			Ledger.Holding h = stores.get(s);
			if (h == null)
			{
				if (s == Store.BANK)
				{
					parts.add(new StoreBreakdown.Part(s, 0, StoreBreakdown.NEVER));
				}
				continue;
			}
			long value = ledger.value(s);
			if (value > 0 || s == Store.BANK || s == Store.INVENTORY)
			{
				parts.add(new StoreBreakdown.Part(s, value, s == Store.BANK || s == Store.SEED_VAULT ? now - h.getSeen() : -1));
			}
		}
		parts.sort((a, b) -> Long.compare(b.value, a.value));
		return parts;
	}

	// The Day book tab.

	private void rebuildDaybook()
	{
		StackPanel stack = new StackPanel(8, 8);
		stack.add(span);
		if (waiting(stack))
		{
			replace(daybook, stack);
			return;
		}
		Report report;
		String title;
		String subtitle;
		Day page = openDay == null ? null : ledger.day(LocalDate.parse(openDay));
		if (page != null)
		{
			report = Report.page(page, LINES);
			title = Format.day(LocalDate.parse(page.getDate()));
			subtitle = "from " + Format.coins(page.getOpen()) + " to " + Format.coins(page.getClose());
			Card banner = new Card(new BorderLayout(6, 0));
			banner.accent(Theme.GOLD_DIM);
			banner.add(Ui.label("One page of the day book", Theme.small(), Theme.TEXT_MUTED), BorderLayout.CENTER);
			banner.add(new CodexButton("Back", false, () -> openDay(null)), BorderLayout.EAST);
			stack.add(banner);
		}
		else
		{
			int s = span.getSelected();
			report = Report.of(ledger, SPAN_DAYS[s], today(), LINES);
			title = s == 0 ? "Today" : s == 3 ? "Since " + Format.day(report.getFrom()) : "The last " + SPANS[s];
			subtitle = "from " + Format.coins(report.getStart()) + " to " + Format.coins(report.getEnd());
		}

		Card head = new Card(new BorderLayout(0, 6));
		head.highlighted(true);
		JPanel top = new JPanel(new BorderLayout());
		top.setOpaque(false);
		JPanel words = new JPanel();
		words.setOpaque(false);
		words.setLayout(new BoxLayout(words, BoxLayout.Y_AXIS));
		words.add(Ui.label(title, Theme.title(), Theme.GOLD_BRIGHT));
		words.add(Ui.label(subtitle, Theme.small(), Theme.TEXT_MUTED));
		top.add(words, BorderLayout.CENTER);
		top.add(Ui.label(Format.signed(report.change()), Theme.title(), Theme.signed(report.change())), BorderLayout.EAST);
		head.add(top, BorderLayout.NORTH);
		head.add(new SplitRows(report.getPlay(), report.getMarket()), BorderLayout.CENTER);
		stack.add(head);

		lines(stack, "Came in", report.getGains(), false);
		lines(stack, "Went out", report.getLosses(), false);
		lines(stack, "Price moves", report.getMovers(), true);
		if (report.getGains().isEmpty() && report.getLosses().isEmpty() && report.getMovers().isEmpty())
		{
			stack.add(note("A quiet page", "Nothing came in or went out yet. Loot, supplies used, trades and price moves all land here as they happen."));
		}

		List<Day> days = new ArrayList<>(ledger.getDays());
		Collections.reverse(days);
		if (!days.isEmpty())
		{
			stack.add(new SectionHeader("Pages", days.size() + (days.size() == 1 ? " day" : " days")));
			long scale = 1;
			for (int i = 0; i < days.size() && i < PAGES; i++)
			{
				scale = Math.max(scale, Math.max(Math.abs(days.get(i).getPlay()), Math.abs(days.get(i).getMarket())));
			}
			for (int i = 0; i < days.size() && i < PAGES; i++)
			{
				Day d = days.get(i);
				stack.add(new DayRow(d, scale, d.getDate().equals(openDay), () -> openDay(d.getDate())));
			}
			if (days.size() > PAGES)
			{
				stack.add(Ui.label("and " + (days.size() - PAGES) + " older pages", Theme.small(), Theme.TEXT_FAINT));
			}
		}
		replace(daybook, stack);
	}

	private void lines(StackPanel stack, String heading, List<Report.Line> lines, boolean drift)
	{
		if (lines.isEmpty())
		{
			return;
		}
		long sum = 0;
		for (Report.Line l : lines)
		{
			sum += drift ? l.getDrift() : l.getValue();
		}
		stack.add(new SectionHeader(heading, Format.signed(sum)));
		JPanel list = new JPanel(new GridLayout(0, 1, 0, 2));
		list.setOpaque(false);
		for (Report.Line l : lines)
		{
			String name = name(l.getItemId());
			long amount = drift ? l.getDrift() : l.getValue();
			Color color = drift ? (amount >= 0 ? Theme.MARKET : Theme.EMBER) : Theme.signed(amount);
			String note;
			if (drift)
			{
				long price = ledger.price(l.getItemId());
				note = price > 0 ? "now " + Format.coins(price) + " each" : "price moved";
			}
			else
			{
				long each = Math.abs(l.getValue() / Math.max(1, Math.abs(l.getQuantity())));
				note = Format.count(l.getQuantity()) + (Math.abs(l.getQuantity()) == 1 || each <= 1 ? "" : " (" + Format.coins(each) + " each)");
			}
			list.add(new ItemRow(l.getItemId(), name, note, Format.signed(amount), color, -1, icons,
				name + ": " + Format.count(l.getQuantity()) + ", " + Format.signed(l.getValue()) + " from play, " + Format.signed(l.getDrift()) + " from prices"));
		}
		stack.add(list);
	}

	private String name(int itemId)
	{
		String name = names.get(itemId);
		return name != null ? name : "Item " + itemId;
	}

	// The Hoard tab.

	private void rebuildHoard()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (ledger == null)
		{
			waiting(stack);
			replace(hoard, stack);
			return;
		}
		List<Report.Line> lines = Report.holdings(ledger, Integer.MAX_VALUE);
		if (lines.isEmpty())
		{
			stack.add(note("Nothing counted yet", "Items with a Grand Exchange price appear here, most valuable first."));
			replace(hoard, stack);
			return;
		}
		long total = Math.max(1, ledger.getTotal());
		long topFive = 0;
		for (int i = 0; i < lines.size() && i < 5; i++)
		{
			topFive += lines.get(i).getValue();
		}
		Card head = new Card(new BorderLayout(0, 4));
		head.highlighted(true);
		head.add(Ui.label(lines.size() + " kinds of item", Theme.title(), Theme.GOLD_BRIGHT), BorderLayout.NORTH);
		head.add(Ui.wrapped("Your five most valuable hold " + Format.percent(topFive / (double) total) + " of your worth."
			+ (ledger.isReady() ? "" : " Open your bank to count the rest."), Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		stack.add(head);

		stack.add(new SectionHeader("Most valuable", "share"));
		JPanel list = new JPanel(new GridLayout(0, 1, 0, 2));
		list.setOpaque(false);
		for (int i = 0; i < lines.size() && i < HOARD; i++)
		{
			Report.Line l = lines.get(i);
			String name = name(l.getItemId());
			long each = ledger.price(l.getItemId());
			String note = each <= 1 ? String.format("%,d", l.getQuantity())
				: l.getQuantity() > 1 ? String.format("%,d x %s", l.getQuantity(), Format.coins(each)) : Format.coins(each) + " each";
			Color color = i == 0 ? Theme.GOLD_BRIGHT : Theme.GOLD;
			list.add(new ItemRow(l.getItemId(), name, note, Format.coins(l.getValue()), color, l.getValue() / (double) total, icons,
				name + ": " + String.format("%,d", l.getQuantity()) + ", worth " + Format.coins(l.getValue())));
		}
		stack.add(list);
		if (lines.size() > HOARD)
		{
			long rest = 0;
			for (int i = HOARD; i < lines.size(); i++)
			{
				rest += lines.get(i).getValue();
			}
			stack.add(Ui.label("and " + (lines.size() - HOARD) + " more, worth " + Format.coins(rest), Theme.small(), Theme.TEXT_FAINT));
		}
		replace(hoard, stack);
	}

	static Card note(String title, String text)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.GOLD_DIM);
		card.add(Ui.label(title, Theme.body(), Theme.GOLD), BorderLayout.NORTH);
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		return card;
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		scroll.revalidate();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		g.setColor(Theme.INK);
		g.fillRect(0, 0, getWidth(), getHeight());
	}
}

package com.codex.ledger.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.ledger.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			Ui.shadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

package com.codex.ledger.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/** The Ledger's mark: a stack of gilt coins with a teal line climbing past it to a bright point. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float stroke = Math.max(0.6f, 0.55f * s);

		// Three coins, the top one face up.
		float cx = x + 6.2f * s;
		float rw = 5.4f * s;
		float rh = 2.1f * s;
		for (int i = 0; i < 3; i++)
		{
			float cy = y + (13.4f - i * 2.6f) * s;
			Path2D edge = new Path2D.Float();
			edge.append(new Ellipse2D.Float(cx - rw, cy - rh + 1.2f * s, rw * 2, rh * 2), false);
			g.setPaint(new GradientPaint(cx - rw, 0, Theme.GOLD_DIM, cx + rw, 0, Theme.mix(Theme.GOLD_DIM, Theme.INK_DEEP, 0.4)));
			g.fill(edge);
			Ellipse2D face = new Ellipse2D.Float(cx - rw, cy - rh, rw * 2, rh * 2);
			g.setPaint(new GradientPaint(cx - rw, cy - rh, Theme.GOLD_BRIGHT, cx + rw, cy + rh, Theme.GOLD));
			g.fill(face);
			g.setColor(Theme.INK_DEEP);
			g.setStroke(new BasicStroke(stroke));
			g.draw(face);
		}
		g.setColor(Theme.alpha(Theme.INK_DEEP, 150));
		g.draw(new Ellipse2D.Float(cx - rw * 0.55f, y + 8.2f * s - rh * 0.55f, rw * 1.1f, rh * 1.1f));

		// The line, rising from the left past the coins.
		Path2D line = new Path2D.Float();
		line.moveTo(x + 1.2f * s, y + 6.6f * s);
		line.lineTo(x + 5.2f * s, y + 4.4f * s);
		line.lineTo(x + 8.4f * s, y + 5.6f * s);
		line.lineTo(x + 13.6f * s, y + 1.8f * s);
		g.setStroke(new BasicStroke(Math.max(2.2f, 2.4f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.INK_DEEP);
		g.draw(line);
		g.setStroke(new BasicStroke(Math.max(1.1f, 1.3f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.TEAL);
		g.draw(line);

		// A bright point where it ends.
		float r = 1.7f * s;
		g.setColor(Theme.alpha(Theme.TEAL, 90));
		g.fill(new Ellipse2D.Float(x + 13.6f * s - r * 1.7f, y + 1.8f * s - r * 1.7f, r * 3.4f, r * 3.4f));
		g.setColor(Theme.mix(Theme.TEAL, Theme.TEXT, 0.5));
		g.fill(new Ellipse2D.Float(x + 13.6f * s - r, y + 1.8f * s - r, r * 2, r * 2));
	}
}

package com.codex.ledger.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/**
 * The change in worth taken apart: play (what was gained or spent) and market (what prices did),
 * each a bar growing right for gold gained and left for gold lost from a gilt centre line.
 */
class SplitRows extends JComponent
{
	private static final int ROW = 20;
	private static final int LABEL = 46;
	private static final int VALUE = 46;

	private final long play;
	private final long market;

	SplitRows(long play, long market)
	{
		this.play = play;
		this.market = market;
		setOpaque(false);
		setPreferredSize(new Dimension(10, ROW * 2));
		setToolTipText("Play is items gained or spent at the day's prices. Market is prices moving on what you held.");
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		long scale = Math.max(1, Math.max(Math.abs(play), Math.abs(market)));
		row(g, 0, "Play", play, scale, play >= 0 ? Theme.GAIN : Theme.LOSS);
		row(g, ROW, "Market", market, scale, market >= 0 ? Theme.MARKET : Theme.EMBER);
		g.dispose();
	}

	private void row(Graphics2D g, int y, String label, long value, long scale, Color color)
	{
		int w = getWidth();
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int mid = y + ROW / 2;
		int base = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label, 0, base);
		String text = Format.signed(value);
		Ui.shadowed(g, text, w - fm.stringWidth(text), base, Theme.mix(color, Theme.TEXT, 0.2));

		int left = LABEL;
		int right = w - VALUE;
		int centre = (left + right) / 2;
		int half = (right - left) / 2;
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(left, mid - 3, right - left, 6, 6, 6));
		float len = (float) (half * Math.min(1, Math.abs(value) / (double) scale));
		if (value != 0)
		{
			len = Math.max(2, len);
			float x = value > 0 ? centre : centre - len;
			g.setPaint(new GradientPaint(centre, 0, Theme.mix(color, Theme.INK, 0.35), value > 0 ? centre + half : centre - half, 0, color));
			g.fill(new RoundRectangle2D.Float(x, mid - 3, len, 6, 6, 6));
		}
		g.setColor(Theme.GOLD);
		g.fillRect(centre, mid - 5, 1, 10);
	}
}

package com.codex.ledger.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.ledger.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
